// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(address depositor, uint256 depositAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        uint256 oldBal;
        try c.balances(depositor) returns (uint256 __r) { oldBal = __r; } catch { return; }
        depositor = address(this);
        try c.Deposit{value: depositAmount}() {} catch { return; }
        uint256 newBal;
        try c.balances(depositor) returns (uint256 __r) { newBal = __r; } catch { return; }
        assertTrue(newBal == oldBal + depositAmount);
    }

    function testFuzz_run(address depositor, uint256 depositAmount) public {
        _run(depositor, depositAmount);
    }

    receive() external payable {}
}
